        {"구절":"호 2:1", "연결점":"로루하마가 루하마로 회복되는 예언", "구분":"구약"},
        {"구절":"롬 9:25-26", "연결점":"바울이 호세아를 인용하여 이방인의 구원을 설명", "구분":"신약"},
        {"구절":"벧전 2:10", "연절점":"전에는 긍휼을 얻지 못하였으나 이제는 긍휼을 얻은 자", "구분":"신약"},
        {"구절":"엡 2:4", "연결점":"긍휼이 풍성하신 하나님의 사랑", "구분":"신약"},
        {"구절":"히 10:26-27", "연결점":"진리를 아는 지식을 받은 후 짐짓 죄를 범하면 남은 것은 심판뿐", "구분":"신약"}
