    표5_매튜헨리: [
        {"영어원문":"Yet the number of the children of Israel shall be as the sand of the sea; even after the severest judgments, God's promises to Abraham shall stand.", "한국어번역":"그러나 이스라엘 자손의 수가 바닷가의 모래 같이 되리니, 가장 혹독한 심판 후에도 아브라함에게 하신 약속은 굳건히 서리라.", "핵심통찰":"하나님의 약속은 심판보다 강하다"},
        {"영어원문":"In the place where it was said, Ye are not my people, there it shall be said, Ye are the sons of the living God; what a glorious change!", "한국어번역":"내 백성이 아니라 한 그곳에서 사신 하나님의 자녀라 할 것이라. 얼마나 영광스러운 변화인가!", "핵심통찰":"심판의 장소가 회복의 장소로 변하는 은혜의 역전"},
        {"영어원문":"They shall not merely be restored to their former dignity, but raised to a higher one—from servants to sons.", "한국어번역":"그들은 단지 이전의 지위로 회복되는 것이 아니라 더 높은 지위로 격상된다 - 종에서 아들로.", "핵심통찰":"하나님의 회복은 원래보다 더 나은 상태로의 격상"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"사신 하나님의 자녀라 - 은혜의 극적 반전", "예화_적용":"하나님의 마지막 말씀은 심판이 아닌 사랑이다"},
        {"대지":"서론", "내용":"9절에서 '내 백성이 아니다'라는 가장 무서운 선고가 내려졌다. 그런데 바로 다음 절에서 놀라운 반전이 일어난다. '사신 하나님의 자녀라 할 것이라!' 이것이 하나님이시다. 심판으로 끝내지 않으시는 분", "예화_적용":"영화에서 가장 감동적인 장면은 절망 후에 찾아오는 반전이다. 하나님의 이야기도 항상 은혜의 반전으로 끝난다"},
        {"대지":"1대지: 바닷가의 모래 같이 (아브라함 약속의 재확인)", "내용":"이스라엘이 아무리 실패해도 아브라함에게 하신 약속은 취소되지 않는다. '바닷가의 모래'는 창 22:17의 직접 인용으로 하나님의 무조건적 언약의 영속성을 보여준다", "예화_적용":"부모가 자녀를 아무리 꾸짖어도 자녀와의 혈연 관계는 끊어지지 않듯, 하나님의 언약은 영원하다"},
        {"대지":"2대지: 그곳에서 (심판의 장소가 회복의 장소로)", "내용":"'내 백성이 아니라 한 그곳에서' 회복이 선언된다. 저주의 장소가 축복의 장소로, 심판의 현장이 회복의 현장으로 변한다. 하나님은 폐허 위에 새것을 세우신다", "예화_적용":"예수님이 돌아가신 골고다가 구원의 장소가 되었듯이, 우리 인생의 가장 아픈 자리가 은혜의 자리가 된다"},
        {"대지":"3대지: 사신 하나님의 자녀 (격상된 신분)", "내용":"단순한 '백성' 회복이 아닌 '사신 하나님의 자녀'로의 격상이다. 종에서 아들로, 피조물에서 하나님의 가족으로. 하나님의 회복은 항상 원래보다 더 좋다", "예화_적용":"탕자가 돌아왔을 때 아버지는 종의 자리가 아닌 아들의 자리를 회복시켜 주셨다 (눅 15:22)"},
        {"대지":"결론", "내용":"로암미에서 '사신 하나님의 자녀'로의 전환은 복음의 핵심이다. 우리는 본래 하나님의 백성이 아니었으나, 그리스도 안에서 하나님의 자녀가 되었다. 이것이 은혜다", "예화_적용":"벧전 2:10 '전에는 백성이 아니더니 이제는 하나님의 백성이요, 전에는 긍휼을 얻지 못하였더니 이제는 긍휼을 얻은 자니라'"}
    ],
