    표5_매튜헨리: [
        {"영어원문":"Say ye unto your brethren, Ammi; and to your sisters, Ruhamah; the names of terror are reversed into names of comfort.", "한국어번역":"너희 형제에게는 암미라, 자매에게는 루하마라 하라. 공포의 이름이 뒤집어져 위로의 이름이 되었다.", "핵심통찰":"하나님은 공포의 이름을 위로의 이름으로 바꾸신다"},
        {"영어원문":"Those that were not a people are now owned as God's people; what a change grace makes!", "한국어번역":"백성이 아니었던 자들이 이제 하나님의 백성으로 인정된다. 은혜가 얼마나 큰 변화를 가져오는가!", "핵심통찰":"은혜의 변화력은 정체성 자체를 바꾼다"},
        {"영어원문":"This happy change was to be proclaimed among themselves, encouraging one another with these comfortable words.", "한국어번역":"이 기쁜 변화는 그들 사이에서 선포되어야 했으니, 이 위로의 말로 서로를 격려해야 했다.", "핵심통찰":"회복의 기쁨은 공동체 안에서 함께 나누어야 한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"암미라 하고 루하마라 하라 - 회복의 새 이름", "예화_적용":"하나님은 우리의 저주를 축복으로 바꾸신다"},
        {"대지":"서론", "내용":"1장의 무거운 심판 이름들이 드디어 바뀌는 순간이다. 로암미가 암미로, 로루하마가 루하마로. 부정의 접두사 '로'가 제거되는 순간, 모든 것이 달라진다. 이것이 은혜의 능력이다", "예화_적용":"범죄 기록이 말소되면 새 사람이 되듯이, 하나님의 은혜는 우리의 과거를 지우고 새 정체성을 주신다"},
        {"대지":"1대지: 암미라 하라 (내 백성이라는 회복)", "내용":"'내 백성 아님'이었던 자가 '내 백성'이 된다. 이것은 단순한 명칭 변경이 아닌 관계의 완전한 회복이다. 끊어졌던 언약이 다시 연결된다", "예화_적용":"의절했던 부모가 다시 자녀를 품에 안으며 '넌 내 자식이야'라고 말하는 순간의 감동"},
        {"대지":"2대지: 루하마라 하라 (긍휼의 회복)", "내용":"'긍휼을 받지 못한 자'가 '긍휼을 받은 자'가 된다. 하나님의 자궁 같은 사랑(라함)이 다시 임한다. 어머니의 사랑이 자녀에게 돌아온다", "예화_적용":"집을 나갔던 자녀가 돌아왔을 때 어머니의 품이 열리듯, 하나님의 긍휼은 돌아오는 자에게 활짝 열려 있다"},
        {"대지":"3대지: 형제자매에게 선포하라 (공동체적 회복)", "내용":"이 회복은 혼자만의 것이 아니다. '너희 형제에게' '너희 자매에게'라는 명령은 공동체 전체가 함께 회복의 기쁨을 나누라는 것이다", "예화_적용":"기쁜 소식은 혼자 간직하는 것이 아니라 함께 나누는 것이다. 구원의 기쁨을 주변에 전하라"},
        {"대지":"결론", "내용":"호세아의 자녀들의 이름이 바뀌듯, 우리의 이름도 바뀌었다. 죄인이 의인으로, 원수가 자녀로, 버림받은 자가 사랑받는 자로. 이 새 이름을 서로에게 선포하자. '당신은 하나님의 백성입니다. 당신은 긍휼을 받은 자입니다'", "예화_적용":"벧전 2:10 '전에는 백성이 아니더니 이제는 하나님의 백성이요 전에는 긍휼을 얻지 못하였더니 이제는 긍휼을 얻은 자니라'"}
    ],
