        {"상황":"자녀의 신앙 이탈로 걱정하는 부모", "성경원리":"부모의 영적 상태가 자녀에게 영향을 미친다. 그러나 기도와 모범을 통해 다음 세대를 세울 수 있다", "실제적용":"자녀를 위해 꾸준히 기도하고, 말보다 삶으로 신앙의 본을 보이라. 포기하지 말라"},
        {"상황":"세대적 죄의 패턴을 끊고 싶은 분", "성경원리":"그리스도 안에서 옛 사람은 죽고 새 사람이 된다 (고후 5:17). 세대적 저주의 사슬은 그리스도 안에서 끊어진다", "실제적용":"과거의 패턴을 인식하고, 그리스도 안에서 새로운 선택을 하라. 필요하면 전문 상담을 받으라"}
