        {"구분":"축복의 원천 착각", "내용":"하나님의 선물을 바알의 것으로 착각", "그리스도연결":"모든 좋은 은사가 위로부터 옴을 가르치신 그리스도 (약 1:17)"},
        {"구분":"떡과 물의 공급자", "내용":"이스라엘의 떡과 물을 공급하시는 하나님", "그리스도연결":"생명의 떡이요 생수이신 그리스도 (요 6:35, 요 4:14)"}
