        {"상황":"자신의 노력으로 모든 것을 이루었다고 생각하는 분", "성경원리":"이스라엘은 하나님의 선물을 자기 노력의 대가로 착각했다. 우리가 가진 모든 것은 하나님의 은혜의 선물이다", "실제적용":"성공의 원천을 돌아보라. 건강, 기회, 만남 - 이 모든 것이 은혜임을 인정하라"},
        {"상황":"하나님보다 다른 것에 의존하는 분", "성경원리":"이스라엘이 여호와 대신 바알을 의존한 것이 영적 간음이었다. 하나님 외의 것에 절대적으로 의존하는 것은 우상숭배", "실제적용":"내 인생에서 하나님의 자리를 차지하고 있는 것이 무엇인지 점검하라. 돈? 명예? 관계? 그것을 내려놓으라"}
