        {"새찬송가":"559", "통일찬송가":"460", "제목":"우리는 주님을 늘 배반하나", "선정이유":"은혜를 받으면서도 배반하는 인간의 죄성"},
        {"새찬송가":"26", "통일찬송가":"34", "제목":"하나님의 크신 사랑", "선정이유":"알아야 할 하나님의 크고 넓은 사랑"},
        {"새찬송가":"460", "통일찬송가":"369", "제목":"지금까지 지내온 것", "선정이유":"지금까지의 모든 것이 하나님의 은혜임을 고백"}
