        {"상황":"하나님의 은사를 잘못 사용하는 분", "성경원리":"이스라엘은 하나님이 주신 금과 은으로 바알 신상을 만들었다. 하나님의 선물을 하나님의 뜻에 반하는 데 사용하는 것은 큰 죄", "실제적용":"당신의 재능, 시간, 돈을 어디에 쓰고 있는가? 하나님이 주신 것을 하나님의 영광을 위해 사용하라"},
        {"상황":"하나님의 존재를 인식하지 못하는 분", "성경원리":"'알지 못하도다'는 하나님의 탄식이다. 하나님은 매 순간 우리에게 선물을 주시지만 우리가 알지 못할 뿐", "실제적용":"하루를 마칠 때 '오늘 하나님이 주신 것'을 돌아보라. 눈을 뜨면 하나님의 은혜가 보인다"}
