        {"구절":"행 14:17", "연결점":"하늘로서 비를 내리시고 결실기를 주시는 하나님의 증거", "구분":"신약"},
        {"구절":"롬 1:21", "연결점":"하나님을 알되 영화롭게도 감사하지도 아니하고", "구분":"신약"}
