    표6_설교자료: [
        {"대지":"제목", "내용":"건져낼 자 없으리라 - 우상의 한계, 하나님의 절대 주권", "예화_적용":"위기의 순간 진짜 의지할 곳이 어디인지 드러난다"},
        {"대지":"서론", "내용":"이스라엘이 의지했던 바알 신들의 눈앞에서 수치가 드러난다. 바알은 지켜보기만 할 뿐 아무 도움이 되지 못한다. 그리고 '내 손에서 건져낼 자 없다'는 하나님의 선언. 우상의 무능력과 하나님의 절대 주권이 동시에 드러나는 순간이다", "예화_적용":"타이타닉호가 침몰할 때 1등석 티켓도, 부자의 재산도, 높은 지위도 아무 소용이 없었다. 위기의 순간 참된 의지처가 드러난다"},
        {"대지":"1대지: 수치를 드러내리니 (숨겨진 죄의 폭로)", "내용":"이스라엘은 자신의 추함을 감추고 있었다고 생각했다. 그러나 하나님이 '드러내시겠다'고 하신다. 숨겨진 죄는 영원히 숨겨지지 않는다", "예화_적용":"눅 12:2 '감추인 것이 드러나지 않을 것이 없고 숨은 것이 알려지지 않을 것이 없다'"},
        {"대지":"2대지: 연인들의 눈 앞에 (우상의 무능력)", "내용":"이스라엘이 믿었던 바알 앞에서 수치를 당한다. 바알은 아무것도 할 수 없다. 의지했던 것의 무능력이 가장 결정적 순간에 드러난다", "예화_적용":"시험장에서 컨닝 페이퍼가 발각되듯, 거짓 의지처는 결정적 순간에 무너진다"},
        {"대지":"3대지: 내 손에서 건져낼 자 없으리라 (하나님의 절대 주권)", "내용":"하나님의 심판에서 건져낼 수 있는 존재는 없다. 이것은 두려운 선언이면서 동시에 위로의 메시지이기도 하다. 하나님의 손이 심판의 손이면 피할 수 없지만, 보호의 손이면 빼앗길 수 없다 (요 10:28-29)", "예화_적용":"같은 하나님의 손이 심판의 손도 되고 보호의 손도 된다. 어느 쪽에 있느냐는 우리의 선택이다"},
        {"대지":"결론", "내용":"당신은 무엇을 의지하고 있는가? 그것이 결정적 순간에도 당신을 지켜줄 수 있는가? 유일하게 참된 의지처는 하나님뿐이다. 하나님의 심판의 손이 아닌 보호의 손 안에 머물라", "예화_적용":"시 46:1 '하나님은 우리의 피난처시요 힘이시니 환난 중에 만날 큰 도움이시라'"}
    ],
