        {"구분":"희락의 상실", "내용":"이스라엘의 모든 기쁨이 빼앗김", "그리스도연결":"충만한 기쁨을 회복시키시는 그리스도 (요 15:11)"},
        {"구분":"예배의 중단", "내용":"하나님과의 교통이 차단됨", "그리스도연결":"새로운 예배의 길을 여신 그리스도 (요 4:23-24)"}
