        {"구절":"신 8:11", "연결점":"삼가 여호와를 잊어버리지 말라", "구분":"구약"},
        {"구절":"렘 2:32", "연결점":"처녀가 그 패물을 잊겠느냐 그러나 내 백성은 나를 잊었다", "구분":"구약"},
        {"구절":"시 106:21", "연결점":"자기를 구원하신 하나님을 잊었도다", "구분":"구약"},
        {"구절":"눅 22:19", "연결점":"나를 기념하여 이것을 행하라 - 기억의 명령", "구분":"신약"},
        {"구절":"계 20:12", "연결점":"책들이 펴졌으며 각각 행위대로 심판을 받았다", "구분":"신약"},
        {"구절":"고후 5:10", "연결점":"그리스도의 심판대 앞에 서서 각각 선악간 보응을 받음", "구분":"신약"},
        {"구절":"히 8:12", "연결점":"저희 불의를 긍휼히 여기고 저희 죄를 다시 기억지 아니하리라", "구분":"신약"}
