        {"상황":"환경 파괴에 대한 책임감을 느끼는 분", "성경원리":"하나님의 비전은 자연과 인간의 화해까지 포함한다. 하나님은 온 창조를 돌보시는 분이다", "실제적용":"자연을 돌보는 것은 하나님의 창조 목적에 동참하는 것이다. 작은 것부터 실천하라"}
