        {"상황":"깨어진 관계의 회복을 바라는 분", "성경원리":"이혼까지 선언한 관계를 하나님이 '영원히' 회복시키신다. 하나님은 깨어진 관계를 더 강하게 회복하시는 분", "실제적용":"관계가 회복되려면 의, 공변됨, 은총, 긍휼, 진실이 기초가 되어야 한다. 감정이 아닌 인격 위에 관계를 세우라"},
        {"상황":"하나님의 약속이 변할까 두려운 분", "성경원리":"'영원히'라는 약속과 하나님의 불변하시는 성품이 이 약속을 보증한다. 하나님은 변하시지 않는다", "실제적용":"히 13:8 '예수 그리스도는 어제나 오늘이나 영원토록 동일하시니라.' 이 진리를 붙잡으라"}
