        {"상황":"자신의 이름(정체성)이 저주받았다고 느끼는 분", "성경원리":"이스르엘이라는 저주의 이름이 축복의 이름으로 바뀌었다. 하나님은 저주의 정체성을 축복의 정체성으로 바꾸시는 분", "실제적용":"과거가 당신의 정체성을 결정하지 않는다. 하나님이 부르시는 새 이름이 당신의 진짜 이름이다"},
        {"상황":"하나님의 축복이 끊어진 것 같은 분", "성경원리":"축복의 연쇄(하나님 → 하늘 → 땅 → 소산 → 우리)의 어딘가가 막힌 것처럼 느껴질 수 있다. 그러나 하나님의 축복의 시스템은 여전히 작동 중이다", "실제적용":"보이지 않는 곳에서 하나님이 축복을 준비하고 계신다. 때가 되면 곡식이 익듯, 때가 되면 축복이 도달할 것이다"}
