    표1_원어분석: [
        {"원어":"כָּרָה (카라)", "의미_문법":"사다, 값을 치르다 - 칼 완료형. 대가를 지불하고 구입함을 의미", "설교포인트":"구속에는 반드시 대가가 따른다. 하나님의 사랑도 무상이 아니라 십자가의 대가가 있다"},
        {"원어":"חֲמֵשׁ עֶשְׂרֵה כֶּסֶף (하메쉬 에스레 케세프)", "의미_문법":"은 열다섯 개 - 노예 한 명의 반값(출 21:32은 은 30). 고멜의 가치가 떨어졌음을 시사", "설교포인트":"죄로 인해 가치가 하락한 인간을 하나님은 전부를 지불하고 사신다"},
        {"원어":"חֹמֶר שְׂעֹרִים (호메르 세오림)", "의미_문법":"보리 한 호멜 - 약 220리터. 은과 함께 물물교환 형태로 지불. 가난한 자의 곡물", "설교포인트":"하나님은 있는 것을 다 동원하여 우리를 구속하신다"},
        {"원어":"לֶתֶךְ (레텍)", "의미_문법":"반 호멜 - 약 110리터. 은과 보리를 합하면 노예 한 명 값(은 30)에 해당", "설교포인트":"구속의 대가가 정확히 채워졌다. 그리스도의 대속도 완전하다"}
    ],
    표2_역사적배경: [
        {"항목":"노예 가격과 구속", "내용":"출 21:32에 의하면 노예 한 명의 가격은 은 30세겔이다. 호세아가 지불한 은 15개와 보리 한 호멜 반은 합쳐서 은 30세겔에 해당하며, 이는 고멜이 노예 시장에서 매매되고 있었음을 시사한다", "목회적활용":"죄의 종이 된 인간의 비참한 상태와 그것을 구속하시는 하나님의 은혜를 대비시켜 설교할 수 있다"},
        {"항목":"보리의 상징적 의미", "내용":"보리는 밀보다 저렴한 가난한 자의 곡물이었다. 은으로 전부를 지불할 수 없어 보리로 보충한 것은 호세아의 가난을 보여주며, 동시에 있는 것 전부를 쏟아 아내를 구속한 것을 나타낸다", "목회적활용":"하나님은 독생자라는 가장 값진 것을 주셔서 우리를 구속하셨다"},
        {"항목":"고대 근동의 노예 시장", "내용":"고멜이 간음의 대가로 노예 신분으로 전락했다. 고대 근동에서 빚이나 범죄로 인해 노예가 되는 것은 흔한 일이었다. 호세아는 노예 시장에서 아내를 되사야 했다", "목회적활용":"죄가 인간을 어떤 상태로 전락시키는지, 그리고 구속의 은혜가 얼마나 큰지를 보여준다"}
    ],
    표3_신학적의미: [
        {"교리":"대속(구속)", "설명":"호세아가 값을 치르고 고멜을 사온 것은 구속의 핵심 원리를 보여준다. 구속(redemption)은 값을 치르고 되사오는 것이다. 그리스도께서 자기 피로 우리를 사셨다", "관련구절":"벧전 1:18-19, 갈 3:13, 고전 6:20"},
        {"교리":"은혜의 대가", "설명":"하나님의 은혜는 무료(free)이지만 값싼(cheap) 것이 아니다. 은혜에는 십자가라는 엄청난 대가가 있다. 호세아의 은 열다섯과 보리는 그리스도의 보혈을 예표한다", "관련구절":"사 55:1, 롬 3:24, 계 5:9"},
        {"교리":"인간의 타락과 무가치", "설명":"고멜의 가격이 노예 값(은 30)인 것은 죄로 인해 타락한 인간의 상태를 보여준다. 그러나 하나님은 이 무가치한 존재에게 무한한 가치를 부여하신다", "관련구절":"롬 3:23, 엡 2:1-3, 사 64:6"}
    ],
    표4_예표론: [
        {"구분":"은 열다섯과 보리로 산 값", "내용":"호세아가 은과 보리를 합쳐 노예 값을 지불하고 고멜을 구속함", "그리스도연결":"그리스도께서 자기 피라는 값으로 우리를 죄에서 구속하심 (벧전 1:18-19)"},
        {"구분":"노예 시장에서의 구매", "내용":"고멜이 노예로 전락하여 시장에서 팔리는 비참한 상태", "그리스도연결":"죄의 종이 된 인간을 그리스도께서 값 주고 사셔서 자유케 하심 (갈 5:1)"},
        {"구분":"있는 것 전부를 지불", "내용":"호세아가 은과 보리를 합하여 가진 것 전부로 지불", "그리스도연결":"그리스도께서 자기 생명이라는 전부를 주셔서 우리를 구속하심 (빌 2:7-8)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"He bought her for fifteen pieces of silver and a homer and a half of barley; a mean price, to show that she was a worthless woman.", "한국어번역":"그는 은 열다섯과 보리 한 호멜 반으로 그녀를 샀다. 이 보잘것없는 가격은 그녀가 가치 없는 여인이었음을 보여준다.", "핵심통찰":"죄로 인해 가치를 잃은 인간의 비참함과 그럼에도 구속하시는 은혜의 대비"},
        {"영어원문":"The price was just the price of a slave, intimating that she was reduced to the lowest condition.", "한국어번역":"그 가격은 정확히 노예의 가격이었으며, 이는 그녀가 가장 낮은 상태로 전락했음을 암시한다.", "핵심통찰":"죄의 결과는 노예 상태로의 전락이며 구속만이 유일한 소망이다"},
        {"영어원문":"She had sold herself for nothing, and now must be redeemed with a price, as the church is said to be purchased with Christ's own blood.", "한국어번역":"그녀는 스스로를 헛되이 팔았으나, 이제 값을 치르고 구속받아야 했다. 이는 교회가 그리스도의 피로 사신 바 된 것과 같다.", "핵심통찰":"스스로를 헛되이 판 자를 값을 치르고 되사시는 것이 구속의 본질이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"값을 치르고 사신 사랑 - 구속의 대가", "예화_적용":"호세아의 구매 행위를 통해 그리스도의 대속을 선포한다"},
        {"대지":"서론", "내용":"노예 시장. 한때 사랑받던 아내가 이제 경매대 위에 서 있다. 호세아는 주머니를 뒤져 은과 보리를 꺼낸다. 가진 것 전부다. 이 장면에 하나님의 구속 이야기가 담겨 있다.", "예화_적용":"링컨이 노예 시장에서 한 흑인 여성을 사서 자유를 준 일화처럼, 호세아도 고멜을 사서 자유를 주었다"},
        {"대지":"1대지: 전락한 상태 (죄의 결과)", "내용":"고멜은 사랑받는 아내에서 노예 시장의 상품으로 전락했다. 이것이 죄의 결과다. 죄는 하나님의 형상으로 지음받은 인간을 가장 비참한 상태로 전락시킨다.", "예화_적용":"마약에 빠진 한 청년이 가정, 직장, 건강 모든 것을 잃고 거리에 나앉았다. 죄의 끝은 항상 전락이다. 당신도 어떤 죄에 붙잡혀 전락하고 있지 않은가"},
        {"대지":"2대지: 값을 치르고 사심 (구속의 대가)", "내용":"호세아는 은 열다섯과 보리 한 호멜 반을 지불했다. 합하면 정확히 노예 한 명 값이다. 구속에는 반드시 대가가 따른다. 하나님의 은혜도 무료이지만 값싸지 않다.", "예화_적용":"은혜는 공짜가 아니다. 본회퍼가 말한 '값싼 은혜'를 경계하라. 그리스도의 피라는 값비싼 대가가 지불되었다. 이 은혜를 가볍게 여기지 말라"},
        {"대지":"3대지: 있는 것 전부를 쏟음 (완전한 헌신)", "내용":"호세아는 은으로 부족하여 보리까지 보태었다. 가진 것 전부를 쏟아 아내를 구속했다. 그리스도도 자기 생명이라는 전부를 쏟아 우리를 구속하셨다.", "예화_적용":"한 아버지가 아들의 수술비를 위해 집과 차를 팔고도 부족하여 자신의 장기까지 기증했다. 사랑은 있는 것 전부를 쏟는 것이다. 그리스도는 생명까지 쏟으셨다"},
        {"대지":"결론", "내용":"당신은 값으로 사신 바 되었다. 헛된 것으로 자신을 팔지 말라. 그리스도의 피값을 기억하고, 그분께 합당한 삶을 살라.", "예화_적용":"이번 주 '나는 값으로 사신 바 되었다'(고전 6:20)를 매일 묵상하라. 사소한 유혹 앞에서 이 진리를 기억하면 승리할 수 있다"}
    ],
