    표8_상담적용: [
        {"상황":"자신의 가치를 느끼지 못하는 분", "성경원리":"고멜은 노예 값밖에 안 되는 존재로 전락했지만, 호세아는 가진 것 전부를 주고 그녀를 샀다. 하나님은 당신에게 독생자의 생명이라는 값을 지불하셨다", "실제적용":"당신의 가치는 하나님이 지불하신 대가로 측정된다. 그리스도의 피 - 이것이 당신의 가치다. 자존감이 낮을 때 십자가를 바라보라"},
        {"상황":"중독에서 벗어나지 못하는 분", "성경원리":"고멜은 음행에 중독되어 노예로 전락했다. 그러나 호세아가 값을 치르고 되사왔다. 중독의 사슬에서 벗어나는 것은 구속의 능력으로 가능하다", "실제적용":"자력으로 중독에서 벗어나기 어렵다. 그러나 그리스도께서 값을 치르고 당신을 자유케 하셨다. 이 사실을 믿고 전문 상담과 함께 영적 회복을 병행하라"},
        {"상황":"과거의 수치심에서 벗어나지 못하는 분", "성경원리":"고멜이 노예 시장에 선 것은 극도의 수치였다. 그러나 호세아가 값을 치르고 데려온 후 새 삶이 시작되었다. 구속은 수치를 영광으로 바꾼다", "실제적용":"과거는 바꿀 수 없지만, 하나님의 구속은 과거의 수치를 은혜의 간증으로 바꾸신다. 수치심을 붙들지 말고 구속의 은혜를 붙들라"}
    ],
